        <div class="pcb-pins right"><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span><span class="pcb-pin"></span></div>
